# area: callables
# hypothesis: Callable assignment uses contravariant parameters and covariant returns, so a positional-only callable with a wider parameter type and a defaulted callable both assign to Callable[[int], float], while a keyword-only function cannot satisfy a positional Callable type.
from collections.abc import Callable
from typing import Protocol, reveal_type


def wide(x: float, /) -> int:
    return int(x)


def with_default(x: int, y: int = 1) -> float:
    return x + y


class Named(Protocol):
    def __call__(self, *, x: int) -> int: ...


def kw_only(*, x: int) -> int:
    return x * 10


def apply(f: Callable[[int], float], v: int) -> float:
    return f(v)


def twice[T](f: Callable[[T], T]) -> Callable[[T], T]:
    def run(v: T) -> T:
        return f(f(v))
    return run


a: Callable[[int], float] = wide  # OK
b: Callable[[int], float] = with_default  # OK
c: Callable[[int], int] = wide  # OK
d: Named = kw_only  # OK
e: Callable[[int], int] = lambda n: n * 2  # OK
t1 = twice(e)
reveal_type(a)
reveal_type(t1)
print(apply(a, 3), apply(b, 3), apply(lambda q: q / 2, 5))
print(c(4), d(x=2), e(5), t1(3))
try:
    apply(kw_only, 3)  # expect-error: keyword-only parameter does not accept a positional argument
except TypeError as exc:
    print('runtime:', type(exc).__name__)
try:
    kw_only(7)  # expect-error
except TypeError as exc:
    print('runtime:', type(exc).__name__)
